  "ui/enchanting_screen.json": "/*File modified by @CrisXolt.\n//(c) Don't use any code design without permission!*/\n{\n  \"enchanting_screen\": {\n    \"variables\": [\n      {\n        \"requires\": \"$desktop_screen\",\n        \"$screen_content\": \"enchanting_dx.center_screen\",\n        \"$screen_bg_content\": \"enchanting_dx.full_screen\",\n        \"$gamepad_cursor\": true\n      },\n      {\n        \"requires\": \"$pocket_screen\",\n        \"$screen_content\": \"enchanting_pocket.enchanting_panel\",\n        \"$gamepad_cursor\": false\n      }\n    ]\n  }\n}",
